properties.lowered:
always @(posedge clk) begin
  if (rst && count !== '0) $error("REQ-FIFO-RESET: reset invariant violated");
end

always @(posedge clk) begin
  if (!(count <= 2)) $error("REQ-FIFO-BOUNDS: invariant violated");
end

logic previous_valid_REQ_FIFO_WRITE;
logic [31:0] previous_REQ_FIFO_WRITE_value;
always @(posedge clk) begin
    if (previous_valid_REQ_FIFO_WRITE && wr_en && count < 2 && count !== previous_REQ_FIFO_WRITE_value + 1'b1) $error("REQ-FIFO-WRITE: gated increment violated");
    previous_REQ_FIFO_WRITE_value <= count;
    previous_valid_REQ_FIFO_WRITE <= 1'b1;
end
